<script setup lang="ts">
import {reactive,computed} from 'vue';import {useWorkbench} from '../stores/workbench';import UiIcon from './UiIcon.vue';const s=useWorkbench();const selected=reactive<Record<string,number[]>>({}),values=reactive<Record<string,any>>({}),ops=reactive<Record<string,string>>({}),free=reactive<Record<string,string>>({});const times=computed(()=>Array.from({length:16},(_,i)=>{const d=new Date((s.spec?.snapshot?.start||s.summary?.time||'').replace(/_/g,'T'));if(Number.isFinite(d.getTime()))d.setMinutes(d.getMinutes()+i*15);return {n:i+1,time:Number.isFinite(d.getTime())?d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}):'时段 '+(i+1)}}));const isPeriod=(q:any)=>/period|time|时段/.test(q.kind+' '+q.text);const isMagnitude=(q:any)=>/magnitude|value|幅度|降低多少|提高多少/.test(q.kind+' '+q.text);function toggle(id:string,n:number){selected[id]??=[];const i=selected[id].indexOf(n);i<0?selected[id].push(n):selected[id].splice(i,1);selected[id].sort((a,b)=>a-b)}async function answer(q:any,value:any){try{await s.answer(q,value)}catch{}}
</script><template><div v-for="q in s.pendingQuestions" :key="q.id" class="question-card" :data-testid="'question-'+q.kind"><div class="question-header"><UiIcon name="chat" :size="15"/><span>{{s.parse?.manual_completion?'待手动补全':'需要你确认'}}</span></div><p>{{q.text}}</p><template v-if="s.parse?.manual_completion"><p class="small-note">{{s.parse.question_policy?.reason||'自动追问已暂停，请手动补全规格。'}}</p><el-button size="small" @click="s.step=3;s.tab='spec'" data-testid="manual-completion">到规格页手动补全</el-button></template><template v-else-if="isPeriod(q)"><div class="period-grid"><button v-for="t in times" :key="t.n" :class="{selected:selected[q.id]?.includes(t.n)}" @click="toggle(q.id,t.n)"><strong>{{t.n}}</strong><span>{{t.time}}</span></button></div><div class="question-actions"><button class="text-button" @click="selected[q.id]=Array.from({length:16},(_,i)=>i+1)">全部时段</button><el-button size="small" type="primary" :disabled="!selected[q.id]?.length" :loading="s.busy" @click="answer(q,selected[q.id])">确认时段</el-button></div></template><template v-else-if="isMagnitude(q)"><div class="question-value"><el-select :model-value="ops[q.id]||'scale'" @update:model-value="ops[q.id]=$event" size="small"><el-option value="scale" label="按比例"/><el-option value="set" label="设为"/><el-option value="add" label="增减量"/></el-select><el-input-number v-model="values[q.id]" size="small" :controls="false" :precision="4" placeholder="手动输入"/></div><p class="small-note">比例 0.8 表示下降 20%；数值由你填写。</p><div class="question-actions"><el-tooltip content="规程默认值未配置"><button class="text-button" disabled>按规程默认值</button></el-tooltip><el-button size="small" type="primary" :disabled="values[q.id]===null||values[q.id]===undefined" :loading="s.busy" @click="answer(q,{operation:ops[q.id]||'scale',value:values[q.id]})">确认幅度</el-button></div></template><template v-else><div class="option-buttons"><el-button v-for="o in q.options||[]" :key="o.label||o.value" size="small" :disabled="o.disabled" @click="answer(q,o.value)">{{o.label||o.value}}</el-button></div><el-input v-model="free[q.id]" size="small" placeholder="补充对象编号或说明"/><el-button size="small" type="primary" :disabled="!free[q.id]" @click="answer(q,free[q.id])">提交补充</el-button></template></div><div v-for="(a,i) in s.answered" :key="i" class="answer-receipt"><UiIcon name="check" :size="14"/><span>{{a.question}}<small>{{Array.isArray(a.answer)?'时段 '+a.answer.join('、'):typeof a.answer==='object'?a.answer.operation+' '+a.answer.value:a.answer}}</small></span></div></template>